import React, { useEffect, useState } from 'react';
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { BarChart3, Bell, Boxes, CreditCard, FileText, Home, LogOut, Package, Receipt, ShoppingCart, UserRound, Users, MoreHorizontal } from 'lucide-react';
import { useAuth } from '../auth/hooks/useAuth';
import { supabase } from '../shared/lib/supabase';

const items = [['Inicio', '/vendedor/inicio', Home], ['Nueva venta', '/vendedor/venta', ShoppingCart], ['Mis ventas', '/vendedor/ventas', BarChart3], ['Cotizaciones', '/vendedor/cotizaciones', FileText], ['Solicitudes', '/vendedor/aprobaciones', Bell], ['Pedidos', '/vendedor/pedidos', Boxes], ['Clientes', '/vendedor/clientes', Users], ['Gastos', '/vendedor/gastos', Receipt], ['Catálogo', '/vendedor/catalogo', Package], ['Inventario', '/vendedor/inventario', Boxes], ['Crédito', '/vendedor/credito', CreditCard], ['Comisión', '/vendedor/comision', UserRound]] as const;
const mobileItems = items.filter(([label]) => ['Inicio', 'Nueva venta', 'Pedidos', 'Catálogo'].includes(label));

export const VendorLayout: React.FC = () => {
  const { profile, sucursalActiva, signOut } = useAuth(); const location = useLocation(); const navigate = useNavigate();
  const [unreadApprovals, setUnreadApprovals] = useState(0);
  const [moreOpen, setMoreOpen] = useState(false);
  useEffect(() => {
    let active = true;
    const load = async () => {
      if (!profile?.id) return;
      const result = await supabase.from('aprobaciones').select('id', { count: 'exact', head: true }).eq('solicitante_id', profile.id).neq('estado', 'pendiente').is('solicitante_visto_at', null);
      if (active) setUnreadApprovals(result.count ?? 0);
    };
    void load();
    const channel = supabase.channel('vendor-approval-badge').on('postgres_changes', { event: '*', schema: 'public', table: 'aprobaciones', filter: profile?.id ? `solicitante_id=eq.${profile.id}` : undefined }, () => void load()).subscribe();
    return () => { active = false; void supabase.removeChannel(channel); };
  }, [location.pathname, profile?.id]);
  const logout = async () => { await signOut(); navigate('/login'); };
  const secondaryItems = items.filter(([label]) => !mobileItems.some(([mobileLabel]) => mobileLabel === label));
  return <div className="altix-safe-bottom min-h-screen bg-[#f7f7f5] text-gray-900 md:pb-0"><aside className="fixed inset-y-0 left-0 hidden w-60 border-r border-gray-200 bg-white md:flex md:flex-col"><div className="flex h-16 items-center border-b border-gray-200 px-5"><span className="text-lg font-semibold tracking-[0.18em] text-gray-950">ALTIX</span><span className="ml-auto text-[10px] uppercase tracking-wide text-gray-400">Venta</span></div><nav className="flex-1 overflow-y-auto px-3 py-4">{items.map(([label, path, Icon]) => <Link key={path} to={path} className={`flex items-center gap-3 border-l-2 px-3 py-2 text-sm ${location.pathname === path ? 'border-blue-600 bg-blue-50 font-medium text-blue-700' : 'border-transparent text-gray-500 hover:bg-gray-50 hover:text-gray-900'}`}><Icon size={16} /><span>{label}</span>{label === 'Solicitudes' && unreadApprovals > 0 && <span aria-label={`${unreadApprovals} respuestas nuevas`} className="ml-auto min-w-5 bg-red-600 px-1.5 py-0.5 text-center text-[10px] font-semibold text-white">{unreadApprovals > 99 ? '99+' : unreadApprovals}</span>}</Link>)}</nav><div className="flex items-center justify-between border-t border-gray-200 p-4"><div className="min-w-0 pr-2"><p className="truncate text-sm font-medium">{profile?.nombre_completo}</p><p className="truncate text-xs text-gray-500">{sucursalActiva?.nombre ?? 'Sin sucursal'}</p></div><button onClick={logout} title="Cerrar sesión" className="p-2 text-gray-400 hover:bg-gray-100 hover:text-gray-900"><LogOut size={17} /></button></div></aside><div className="min-h-screen md:pl-60"><header className="flex h-16 items-center justify-between border-b border-gray-200 bg-white px-4 md:hidden"><span className="text-base font-semibold tracking-[0.16em]">ALTIX</span><button onClick={logout} title="Cerrar sesión" className="min-h-11 min-w-11 p-2 text-gray-500"><LogOut size={18} /></button></header><main className="mx-auto max-w-7xl px-4 py-5 sm:px-6 sm:py-6 lg:px-8"><Outlet /></main><div className="fixed inset-x-0 bottom-0 z-40 border-t border-gray-200 bg-white/95 px-2 pb-[env(safe-area-inset-bottom)] shadow-[0_-4px_14px_rgba(0,0,0,0.06)] backdrop-blur md:hidden"><nav className="mx-auto grid max-w-lg grid-cols-5">{mobileItems.map(([label, path, Icon]) => <Link key={path} to={path} className={`flex min-h-14 flex-col items-center justify-center gap-1 text-[10px] ${location.pathname === path ? 'font-semibold text-blue-700' : 'text-gray-500'}`}><Icon size={19} /><span>{label === 'Nueva venta' ? 'Venta' : label}</span></Link>)}<button type="button" onClick={() => setMoreOpen((value) => !value)} className={`flex min-h-14 flex-col items-center justify-center gap-1 text-[10px] ${moreOpen ? 'font-semibold text-blue-700' : 'text-gray-500'}`}><MoreHorizontal size={19} /><span>Más</span></button></nav>{moreOpen && <div className="absolute bottom-full inset-x-2 mb-2 grid grid-cols-2 gap-1 rounded-xl border border-gray-200 bg-white p-2 shadow-xl">{secondaryItems.map(([label, path, Icon]) => <Link key={path} to={path} onClick={() => setMoreOpen(false)} className="flex min-h-11 items-center gap-2 rounded-lg px-3 text-sm text-gray-700 hover:bg-gray-50"><Icon size={16} />{label}{label === 'Solicitudes' && unreadApprovals > 0 ? ` (${unreadApprovals > 99 ? '99+' : unreadApprovals})` : ''}</Link>)}</div>}</div></div></div>;
};
